package com.jarvis.tools.taskplan;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.jarvis.common.companion.*;
import org.springframework.stereotype.Service;
import java.time.Instant;
import java.util.*;

/** Server-owned task plans; all mutation callbacks share the task engine's state monitor. */
@Service
public class DynamicPlanService {
    public interface Observer {void changed(String owner,String type,String taskId,DynamicPlan plan);}
    public record Evidence(String evidenceRef,String taskId,String tool,String operation,boolean success,Instant timestamp) {}
    private final CompanionDocumentStore store;private final ObjectMapper mapper;
    private volatile Object monitor=this;private Observer observer=(o,t,id,p)->{};
    private final Map<List<String>,String> tasks=new HashMap<>();
    private static final Set<String> STEP_TERMINAL=Set.of("COMPLETED","FAILED","SKIPPED","CANCELLED");
    public DynamicPlanService(CompanionDocumentStore store,ObjectMapper mapper){this.store=store;this.mapper=mapper.copy().findAndRegisterModules();}
    public void attach(Object monitor,Observer observer){this.monitor=monitor;this.observer=observer;}
    public void register(String owner,String taskId,String state){synchronized(monitor){tasks.put(List.of(owner,taskId),state);}}
    public void requireActive(String owner,String taskId){synchronized(monitor){String state=tasks.get(List.of(owner,taskId));if(!Set.of("QUEUED","RUNNING","RETRYING","WAITING_FOR_AUTHORIZATION").contains(state==null?"":state))throw new IllegalArgumentException("Task is not active or not owned");}}
    public Optional<DynamicPlan> find(String owner,String taskId){synchronized(monitor){return store.find(owner,"plan",taskId).map(d->decode(d.body(),DynamicPlan.class));}}
    public List<DynamicPlan> revisions(String owner,String taskId){synchronized(monitor){return store.documents(owner,"plan-revision",taskId+"/").stream().map(d->decode(d.body(),DynamicPlan.class)).sorted(Comparator.comparingLong(DynamicPlan::revision)).toList();}}
    public DynamicPlan create(String owner,String taskId,String title,List<String> titles){synchronized(monitor){requireActive(owner,taskId);if(find(owner,taskId).isPresent())throw new IllegalArgumentException("Task already has a plan");if(titles==null||titles.isEmpty()||titles.size()>100)throw new IllegalArgumentException("A plan needs 1..100 steps");Instant now=Instant.now();var steps=new ArrayList<DynamicPlan.Step>();for(String t:titles)steps.add(new DynamicPlan.Step(UUID.randomUUID().toString(),PublicText.required(t,240),null,steps.size(),"PENDING",null,null,null,null,null));return save(owner,new DynamicPlan(UUID.randomUUID().toString(),taskId,1,PublicText.required(title,240),now,now,"ACTIVE",steps,0,steps.size()),"task.plan.created");}}
    private DynamicPlan editable(String owner,String id,long revision){requireActive(owner,id);DynamicPlan plan=find(owner,id).orElseThrow(()->new IllegalArgumentException("Plan not found"));if(plan.revision()!=revision)throw new IllegalArgumentException("Plan revision conflict");if(!plan.status().equals("ACTIVE"))throw new IllegalArgumentException("Plan is terminal");return plan;}
    public DynamicPlan add(String owner,String id,long revision,String title,String description,int position){synchronized(monitor){var p=editable(owner,id,revision);if(p.steps().size()>=100||position<0||position>p.steps().size())throw new IllegalArgumentException("Invalid step position/capacity");var steps=new ArrayList<>(p.steps());steps.add(position,new DynamicPlan.Step(UUID.randomUUID().toString(),PublicText.required(title,240),PublicText.optional(description,1000),position,"PENDING",null,null,null,null,null));return mutate(owner,p,steps,"ACTIVE","task.plan.updated");}}
    public DynamicPlan update(String owner,String id,long revision,String stepId,String status,String summary,String error,String evidenceRef){synchronized(monitor){var p=editable(owner,id,revision);var steps=new ArrayList<>(p.steps());int index=-1;for(int i=0;i<steps.size();i++)if(steps.get(i).stepId().equals(stepId))index=i;if(index<0)throw new IllegalArgumentException("Step not found");var previous=steps.get(index);
        if(STEP_TERMINAL.contains(previous.status())&&!previous.status().equals("FAILED") || !(previous.status().equals("PENDING")?Set.of("IN_PROGRESS","SKIPPED","CANCELLED"):previous.status().equals("FAILED")?Set.of("IN_PROGRESS"):Set.of("COMPLETED","FAILED","SKIPPED","CANCELLED","RETRYING","IN_PROGRESS")).contains(status))throw new IllegalArgumentException("Invalid step transition");
        if(status.equals("COMPLETED")){Evidence receipt=store.find(owner,"evidence",id+"/"+evidenceRef).map(d->decode(d.body(),Evidence.class)).orElseThrow(()->new IllegalArgumentException("Verified tool evidence required"));if(!receipt.success()||!receipt.taskId().equals(id)||previous.startedAt()==null||receipt.timestamp().isBefore(previous.startedAt()))throw new IllegalArgumentException("Evidence must succeed after this step starts");}
        if(status.equals("SKIPPED")&&(summary==null||summary.isBlank()))throw new IllegalArgumentException("Skipped steps require a reason");
        Instant now=Instant.now();steps.set(index,new DynamicPlan.Step(previous.stepId(),previous.title(),previous.description(),index,status,status.equals("IN_PROGRESS")?now:previous.startedAt(),STEP_TERMINAL.contains(status)?now:null,PublicText.optional(summary,1000),PublicText.optional(error,1000),status.equals("COMPLETED")?evidenceRef:null));return mutate(owner,p,steps,"ACTIVE","task.plan.step.updated");}}
    public DynamicPlan reorder(String owner,String id,long revision,List<String> ids){synchronized(monitor){var p=editable(owner,id,revision);if(ids==null||ids.size()!=p.steps().size()||new HashSet<>(ids).size()!=ids.size())throw new IllegalArgumentException("Reorder requires every step exactly once");var map=new HashMap<String,DynamicPlan.Step>();p.steps().forEach(s->map.put(s.stepId(),s));var steps=new ArrayList<DynamicPlan.Step>();for(String step:ids){if(!map.containsKey(step))throw new IllegalArgumentException("Unknown step");steps.add(map.get(step));}return mutate(owner,p,steps,"ACTIVE","task.plan.updated");}}
    public DynamicPlan complete(String owner,String id,long revision){synchronized(monitor){var p=editable(owner,id,revision);if(p.steps().stream().anyMatch(s->!Set.of("COMPLETED","SKIPPED").contains(s.status())))throw new IllegalArgumentException("Plan contains unfinished or failed steps");return mutate(owner,p,p.steps(),"COMPLETED","task.plan.completed");}}
    public boolean verifiedComplete(String owner,String id){synchronized(monitor){var p=find(owner,id);if(p.isEmpty())return true;if(p.get().status().equals("COMPLETED"))return true;if(p.get().status().equals("ACTIVE")&&p.get().steps().stream().allMatch(s->Set.of("COMPLETED","SKIPPED").contains(s.status()))){complete(owner,id,p.get().revision());return true;}return false;}}
    public void taskState(String owner,String id,String state,boolean recovery){synchronized(monitor){register(owner,id,state);if(Set.of("QUEUED","RUNNING","RETRYING","WAITING","COMPLETED").contains(state)&&!recovery)return;var optional=find(owner,id);if(optional.isEmpty()||!optional.get().status().equals("ACTIVE"))return;var p=optional.get();Instant now=Instant.now();var steps=p.steps().stream().map(s->STEP_TERMINAL.contains(s.status())?s:new DynamicPlan.Step(s.stepId(),s.title(),s.description(),s.position(),"CANCELLED",s.startedAt(),now,null,recovery?"Interrupted by backend restart":"Task no longer executing",null)).toList();mutate(owner,p,steps,recovery?"INTERRUPTED":Set.of("FAILED","PARTIALLY_COMPLETED").contains(state)?"FAILED":"CANCELLED","task.plan.updated");}}
    public Evidence recordEvidence(String owner,String id,String tool,String operation,boolean success){synchronized(monitor){requireActive(owner,id);if(tool.equalsIgnoreCase("taskplan")||tool.equalsIgnoreCase("plan"))throw new IllegalArgumentException("Planning calls cannot verify executable work");var receipt=new Evidence(UUID.randomUUID().toString(),id,tool,operation,success,Instant.now());put(owner,"evidence",id+"/"+receipt.evidenceRef(),receipt);return receipt;}}
    public void forget(String owner,String id){synchronized(monitor){tasks.remove(List.of(owner,id));}}
    public void delete(String owner,String id){synchronized(monitor){store.delete(owner,"plan",id);store.deletePrefix(owner,"plan-revision",id+"/");store.deletePrefix(owner,"evidence",id+"/");tasks.remove(List.of(owner,id));}}
    private DynamicPlan mutate(String owner,DynamicPlan p,List<DynamicPlan.Step> raw,String state,String event){var steps=new ArrayList<DynamicPlan.Step>();for(var s:raw)steps.add(new DynamicPlan.Step(s.stepId(),s.title(),s.description(),steps.size(),s.status(),s.startedAt(),s.completedAt(),s.resultSummary(),s.error(),s.evidenceRef()));return save(owner,new DynamicPlan(p.planId(),p.taskId(),p.revision()+1,p.title(),p.createdAt(),Instant.now(),state,steps,(int)steps.stream().filter(s->s.status().equals("COMPLETED")).count(),steps.size()),event);}
    private DynamicPlan save(String owner,DynamicPlan p,String event){try{String body=mapper.writeValueAsString(p);store.putAll(List.of(new CompanionDocumentStore.Document(owner,"plan",p.taskId(),body,Instant.now()),new CompanionDocumentStore.Document(owner,"plan-revision",p.taskId()+"/"+p.revision(),body,Instant.now())));}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException(e);}var history=revisions(owner,p.taskId());for(int i=0;i<history.size()-200;i++)store.delete(owner,"plan-revision",p.taskId()+"/"+history.get(i).revision());observer.changed(owner,event,p.taskId(),p);return p;}
    private void put(String owner,String kind,String id,Object value){try{store.put(new CompanionDocumentStore.Document(owner,kind,id,mapper.writeValueAsString(value),Instant.now()));}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException("Could not serialize public plan state",e);}}
    private <T>T decode(String json,Class<T> type){try{return mapper.readValue(json,type);}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException("Corrupt companion plan history",e);}}
}
